// ?hasAnyBuildFacility@Team@@QBE_NXZ
// partial score=0.95 date=2026-09-15
// cl: /DNDEBUG /DWIN32 /MD /EHsc /Ireference/shims/objectdlink
// Team::hasAnyBuildFacility at RVA 0x000EF340 has a 99-byte boundary.
// Matched TeamPrototype::hasAnyBuildFacility names the member call.
// Retail +0x25/+0x2c branch to the flag load at +0x33, not past it.
// Thus a template without an override still supplies the flag. A null template
// also reaches that load in retail; preserving the existing crash is intentional.
// This body reproduces the prologue/PMF registers and both override branches.
// It remains 95 bytes: MSVC removes the redundant test esi,esi/je at +0x3d.
// ReadWriteBarrier and an explicit iterator copy constructor did not help.
// Disabling global optimization lost the entire shape (111 bytes).
#include "ObjectDlinkPmf.h"
class Overridable {
public:
 const Overridable *getFinalOverride() const;
 void *vptr;
 Overridable *next;
};
class TemplateView { public: void *vptr; Overridable *value; };
class ThingTemplate { public: unsigned char pad[0x486]; unsigned char facility; };
template<class T> class Iterator {
public:
 typedef T *(T::*Next)() const;
 Iterator(T *p, Next n): p_(p), n_(n) {}
 bool done() const { return p_ == 0; }
 T *cur() const { return p_; }
 void advance() { if (p_) p_ = (p_->*n_)(); }
private:
 T *p_;
 Next n_;
};
class Team {
public:
 bool hasAnyBuildFacility() const;
 void *vptr; void *proto; void *id; Object *head;
 Iterator<Object> members() const { return Iterator<Object>(head, Object::dlink_next_TeamMemberList); }
};
bool Team::hasAnyBuildFacility() const {
 for (Iterator<Object> iter = members(); !iter.done(); iter.advance()) {
  Overridable *value = ((TemplateView *)iter.cur())->value;
  if (value && value->next)
   value = (Overridable *)value->next->getFinalOverride();
  if (((ThingTemplate *)value)->facility) return true;
 }
 return false;
}
